  (1010000001, 1, 1, '01-01', '1月1日', 'https://zh.wikipedia.org/wiki/1%E6%9C%881%E6%97%A5', 'e3d043585955a478f8e80313ce13b70df8a77f5258acb3396fcdc6de65826b9b', 356, '<!DOCTYPE html>
INSERT INTO `today_history_item` (`ID`, `PAGE_ID`, `HISTORY_KEY`, `ITEM_TYPE`, `ERA_TYPE`, `SECTION_TITLE`, `EVENT_YEAR`, `SORT_NO`, `ITEM_HASH`, `CONTENT`) VALUES
  (1010000001001, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', -4713, 1, '4893b53c5073877b696c98da230a38bdb036a67b98ef37e17530c6bf6c3446e1', '前4713年：中午12点儒略日开始计算。'),
  (1010000001002, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', -153, 2, 'e32987fc6e351989c37475dc53498514719b804393a1e7159156d3d0c00ec973', '前153年：罗马执政官职务开始。'),
  (1010000001003, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', -45, 3, '043360662797a284ac04450ba2b2b1653abf6e942be1dcbeb2996337e32ac271', '前45年：罗马共和国独裁官尤利乌斯·凯撒规定开始使用儒略历，取代旧有的罗马历。'),
  (1010000001004, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', -42, 4, '5ba94a635d8c5e44e98be0eab9dd3f811a3573a520103e97cfb93cfdc826fead', '前42年：罗马元老院在凯撒死后，使其神格化。'),
  (1010000001005, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 193, 5, '4188a74e17d76ced2ef88833f13f8c29069f3a6f867d4695957de26bbf5c331f', '193年：佩蒂奈克斯即位罗马皇帝。'),
  (1010000001006, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 404, 6, 'a0314a5ee319042da1280b1e1db2b4093fd40e24184d1278e75a5cff9a2d5483', '404年：东晋将领桓玄正式称帝，国号楚。'),
  (1010000001007, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 404, 7, '2f7ab0abe5fd560b6e5bd49d0979004ff3c76a1f1429574588d52eb7603359f3', '404年：在罗马最后一次角斗士比赛纪录。'),
  (1010000001008, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 630, 8, '4f13fe187c87def2a0b6c81bd3554f6ed60e76a0890fce64492aa27ad95f9669', '630年：伊斯兰教先知穆罕默德带领军队向麦加进发，兵不血刃就夺取了圣地。'),
  (1010000001009, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 976, 9, '88ed30436af0c8aac2a1e337e79c07356cdd2a709554ac0db05c9b205d51fb04', '976年：南唐后主李煜被俘，南唐灭亡。'),
  (1010000001010, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 990, 10, '3e685563a53129187d7171d6ec2d9e027cabe957cdf60d1ee21885e84ea58139', '990年：基辅罗斯采用儒略历。'),
  (1010000001011, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 1085, 11, 'ea25cc41c00cf1fda61d2ce074f4e43b61bb80bdf133044510197b0837347753', '1085年：《资治通鉴》进献给宋神宗。'),
  (1010000001012, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 1438, 12, '9e4c8eba00e48687521a14ea5966428bc9994fc090f4463238e2836a7eedc663', '1438年：阿尔布雷希特二世加冕为匈牙利国王。'),
  (1010000001013, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 1600, 13, 'e7366b32958cfa7877f1e6a358c5288e4d54761fd70481ec8c2fa076ce9f52a1', '1600年：苏格兰采用儒略历。'),
  (1010000001014, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 1700, 14, 'a83e80241a336cd17ecd859b78a0955edebbe44de88ea83709af83e61933eda0', '1700年：俄罗斯采用儒略历。'),
  (1010000001015, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 1773, 15, '4483903bc21b2e4c4f061982cdce09a407528e3ca25e5123fba4184e40a2af95', '1773年：英国牧师约翰·牛顿为奥尔尼新年布道会创作圣诗《奇异恩典》，但与当前版本有所差异。'),
  (1010000001016, 1010000001, '01-01', 'EVENT', 'PRE_19TH', '大事记', 1785, 16, 'c4ce6b23e32a8c08bfc982c26c653c38c2253542d60cf877b1a8004e84dd0bc2', '1785年：伦敦泰晤士报首次出版。'),
  (1010000001017, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1801, 1, '57c61b7ddb89ccb6fbb87214fafa5b507c31f9f7910b76abe99be20dc1e8df9b', '1801年：荷兰东印度公司解散。'),
  (1010000001018, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1801, 2, '83a4344566ad534e353d3fddc7d4ebbd091c18e40708a8238fa583e1105c4b3a', '1801年：大不列颠王国和爱尔兰王国根据《联合法案》合并，成立大不列颠及爱尔兰联合王国。'),
  (1010000001019, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1801, 3, 'e6ddedcd985656c5ed6cea6017da0468b9ae5bd34967a0d8121b7f26130e5935', '1801年：意大利天文学家朱塞普·皮亚齐发现位于矮行星谷神星并以农业女神刻瑞斯命名，这是第一颗被发现的小行星。'),
  (1010000001020, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1804, 4, '4f508b795d86fc6c60f5421b440f1b42e8c0297624c051404c56eb3f3fe37e13', '1804年：法兰西第一共和国在加勒比海的殖民地法属圣多明戈宣布独立，成立海地第一帝国。'),
  (1010000001021, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1806, 5, 'be308ae7d83e87b4756f0cc5c43061b5a145436ba2e3424eca4e83f76057be73', '1806年：法国共和历被弃用。'),
  (1010000001022, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1808, 6, '0d6ffb8b3b6bdd8cea405a0b64cb94477ba91f65e2f5c4c11a9575ea7d6ded2d', '1808年：美国禁止进口奴隶。'),
  (1010000001023, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1810, 7, '8a2d35ca173e27d960e5782564a91d7eab4a3472c0b820c8a887c4791e825dc4', '1810年：拉克伦·麦觉理成为新南威尔士州总督，并在澳洲殖民地的社会、经济和建筑发展的塑造上扮演重要角色。'),
  (1010000001024, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1818, 8, 'b8923871f6aa10041f7f0cbf00c14a80a846c2700b75c1a35075bf85e9476854', '1818年：英国作家玛丽·雪莱的科幻小说《科学怪人》于伦敦首次匿名出版。'),
  (1010000001025, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1844, 9, '9ab39036f9d39c4001a5266a9d0527f78cda25c1df30ac9272866e17f27dd1a2', '1844年：根据《南京条约》，宁波开埠。'),
  (1010000001026, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1861, 10, '78a20da9a495e56247627e36a0a5b0b1a33297f28a77051d0dfece3cd3e5d63b', '1861年：波费里奥·迪亚斯攻占墨西哥城。'),
  (1010000001027, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1863, 11, '9c10553aa0668a4d575e0b4ef4b4b37e94fb80daecb340cefcdf4afa0f5c7534', '1863年：美国总统亚伯拉罕·林肯发表之《解放奴隶宣言》正式生效，确保位于美利坚邦联州份之黑奴应享有自由，然边境州及美利坚联邦所属州份不在此限。'),
  (1010000001028, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1873, 12, '6f2d8862d3d361628891cca89d75c3c01de30a4f0ec8b5956c39ff0c411e03b3', '1873年：日本采用公历。'),
  (1010000001029, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1886, 13, 'c17f666da49700fe201b674cd36bf4194fcee0564776929741cd464d2dc54eaf', '1886年：英国宣布缅甸并入英属印度。'),
  (1010000001030, 1010000001, '01-01', 'EVENT', 'NINETEENTH', '大事记', 1896, 14, 'f2127ab5237d4e441462005803381f191db94e790b7f6d3746d189c76d0ce9ef', '1896年：芝山岩学务部学堂六名教师遭台湾抗日人士刺杀身亡，嗣后日本政府特立碑设祠纪念。'),
  (1010000001031, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1901, 1, 'eacbaad2f7b5c47bb87b59823329146491895c962210c351b2abadfbcf424b83', '1901年：英国在澳洲的六个海外殖民地合并成立澳洲联邦，埃德蒙·巴顿成为首任总理。'),
  (1010000001032, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1912, 2, 'bde42236349c1f93a8a97147a0a4f8f8ee40c0d9a9ebb98dd29df1d973a85695', '1912年：孙中山在南京总统府宣誓就任中华民国临时大总统，中华民国成立。'),
  (1010000001033, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1914, 3, '4f99e4df13aa708e24703b9f6cce5218f4e4fd6597be53b486dd0158c8a30686', '1914年：世界第一条民航客机定期航线在美国佛罗里达州开始运营，航线距离为35公里。'),
  (1010000001034, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1916, 4, 'fcf2c3c628f9bb2144ff054b1e2fcb6d397b88df529032fa82d253846571b6c8', '1916年：袁世凯称帝。'),
  (1010000001035, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1917, 5, '9a49f409c4c8248904c16cb20fcafe233b4c55af5738d3e79cfb987bc8a94053', '1917年：胡适在《新青年》第二卷第五号发表《文学改良刍议》一文，发起新文化运动。'),
  (1010000001036, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1923, 6, 'f03e94be59b259823ce6efbfd70c5a26a2c76e56b9ec83d2f325c3cd1eeed72d', '1923年：孙中山发表《中国国民党宣言》。'),
  (1010000001037, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1926, 7, 'c50bfd71efdd2dd0daab91357ab8d2a2146a3b1a347162ef4889a4e9f351a97d', '1926年：中国国民党第二次全国代表大会召开。'),
  (1010000001038, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1926, 8, '0c83876a165753645b87b0c71819e55454ba9cf2025cc01466e22d1c110df093', '1926年：爱尔兰首家广播电台2RN开始播送节目。'),
  (1010000001039, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1929, 9, '36e6bc0bf709ac0655844ceb833e6afd5dc7f5279e95ac5af261867891448237', '1929年：国民革命军编遣会议召开。'),
  (1010000001040, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1933, 10, '52d7b69df08ae9d9d422b5ce65a0c96e1a4a4f336b9ee8ceadfd849faa93a4c8', '1933年：中国驻檀香山领事馆落成。'),
  (1010000001041, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1934, 11, 'df6b4d07e37a00d8cc0c022aa2fc98229db354eafe018403a1be60938e3afe3c', '1934年：德国实施优生法，能对遗传病患者强制施行绝育手术。'),
  (1010000001042, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1942, 12, 'a4e122565e6efb661fe63feda9e684e191c1700fc45d2855812b6b490cac6b69', '1942年：美国、英国、中华民国、苏联等盟国签订《联合国家宣言》，计划在二战后成立联合国。'),
  (1010000001043, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1946, 13, '8a5d0c3174161f2e7feb09c928680aa136805f4cf74cb953aa4a8eb434f5c889', '1946年：日本昭和天皇发表《人间宣言》，天皇作为“现人神”的地位，宣告天皇也是仅具有人性的普通人。'),
  (1010000001044, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1948, 14, 'a336f8aed271bcbf10f3d6ac86758c1fc8168a44eb36ece3a9236117cc1e1acd', '1948年：中国国民党革命委员会在香港成立。'),
  (1010000001045, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1949, 15, '3234b62c777719cbaf5a6c396eb3b8f59266482326e99ad27424601b0b9b4d33', '1949年：联合国促成克什米尔停火。'),
  (1010000001046, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1950, 16, '9ca2248833f0c6c0227bab692fada1445a2a6b817463cf0ddcbde85f5208d469', '1950年：巴黎统筹委员会成立，审查对社会主义国家的出口贸易。'),
  (1010000001047, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1953, 17, 'df6a0c0a39416f091e39135f35e6c6f5c2da7483c64e3cbf6b6c582f49daf7d1', '1953年：中华人民共和国一五计划开始实行。'),
  (1010000001048, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1956, 18, '780ac677c3defd5dec70fbd06ff0a6673896477053c401d57bb1972532850327', '1956年：埃及王国和联合王国在北非的共管地英埃苏丹宣布独立，成立苏丹共和国。'),
  (1010000001049, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1957, 19, '9a513008b5dd7b0a74cc5a2eeeb6eefd7a805e8d3ac4c82cb1ee33e8df00fc60', '1957年：萨尔地区在第二次世界大战后重归德国。'),
  (1010000001050, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1958, 20, 'd84614e81647f09b4c5f1f8d75bedf75532f7ac45146bfe0a43f24dacae19202', '1958年：国际天文学界建立了第一个原子时系统。'),
  (1010000001051, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1958, 21, 'a2185802ab31e7c38c9952353ddd38a102c0ea8d1fe2e9575dbb41eadfc92af4', '1958年：欧洲经济共同体共同市场成立。'),
  (1010000001052, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1959, 22, '8002ef9fb0c34799a0618ed72953690e23ad01f9a927fddbc9253d6ea3283532', '1959年：菲德尔·卡斯特罗领导的革命军控制古巴首都哈瓦那，富尔亨西奥·巴蒂斯塔政权垮台。'),
  (1010000001053, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1960, 23, 'b34c25ac0908ba9565c514e13f6353095c296859f6ec6546ccf3c35210d7e33f', '1960年：法国在西非的国际联盟托管地法属喀麦隆宣布独立，成立喀麦隆共和国。'),
  (1010000001054, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1962, 24, '9d9bae7113787e7ae8530162d143adc1efb63cf2b6a396a317eabbda9245f166', '1962年：新西兰在波里尼西亚的联合国托管领土西萨摩亚宣布独立，成立西萨摩亚独立国。'),
  (1010000001055, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1963, 25, '5e51a4647350da2c0d8db043f885e47cbe3576a385440c8ebff6b25dedf5739c', '1963年：香港警察队少年罪犯调查组成立。'),
  (1010000001056, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1963, 26, 'bf9e4ee59d483011130d6fc490c648e7e01ade2501117de20e83e7ac1ffcf24d', '1963年：日本最早的电视动画《铁臂阿童木》在富士电视台开播。'),
  (1010000001057, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1965, 27, 'fb893357aae007b8ca7e181c81a4fa2df84ed3cf7474a815df93fe28faa3d188', '1965年：法塔赫（巴勒斯坦民族解放运动）领导的巴勒斯坦武装斗争开始。'),
  (1010000001058, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1970, 28, '5dc659937803c383311a270d1340563c21ca009afc86570f94364d9b25679b87', '1970年：UNIX时间的开始。'),
  (1010000001059, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1972, 29, 'baa3aa8dba73bdd4e9499af714efcbf1d781ad9143336c90e77c7bd9114dbf5a', '1972年：奥地利籍库尔特·瓦尔德海姆成为联合国第4任秘书长。'),
  (1010000001060, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1973, 30, '7ce00feefe184b1eb74a96eb95cbc1972b58f91d6ed8b47f7706deebb9241bb6', '1973年：英国、爱尔兰和丹麦加入欧洲经济共同体。'),
  (1010000001061, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1978, 31, 'd6fe1fb472fea0241efc4090cad0d04789e06f6f5c750e6cc566a7d44a0e884f', '1978年：印度航空855号班机从孟买起飞后坠海，213人死亡。'),
  (1010000001062, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1979, 32, '99f2c908c69fe53d99a9203c05c43137d89b56846ff61de1ec630f7a454d4f17', '1979年：全国人民代表大会常务委员会发表《告台湾同胞书》，停止从1958年开始的对大金门等岛屿的炮击。'),
  (1010000001063, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1979, 33, '046159b082bbccf8ee1398bf33de219e6f95f40c063615144c467edbc87b6742', '1979年：中华人民共和国政府和美利坚合众国政府相互承认并建立中美关系，同时美国与中华民国政府断交。'),
  (1010000001064, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1982, 34, '9eb257acd85246f3430cfa54df7b42af6f6c7e20ee74bc57b43dd73cc6c718e8', '1982年：秘鲁籍佩雷斯·德奎利亚尔成为联合国第5位秘书长。'),
  (1010000001065, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1983, 35, '64ff9b0d0c775d1b365c5f47e209176771f65cd5c19f703128fa316b17e5ab1b', '1983年：ARPANET将其网络传输协定由网络控制程式改为TCP/IP协定套组，成为互联网的前身。'),
  (1010000001066, 1010000001, '01-01', 'EVENT', 'TWENTIETH', '大事记', 1984, 36, '38b5a559aab66c417552084660d45281ef7a640672317f9eccee2c1001464dbf', '1984年：英国在东南亚的保护国文莱达鲁萨兰国宣布独立。'),
